<?php
require_once __DIR__ . '/../includes/layout.php';
require_role(['super_admin']);
$stmt=db()->query("SELECT s.id,s.name,s.code,s.status,COALESCE(u.users,0) users,COALESCE(st.students,0) students,sp.name plan FROM schools s LEFT JOIN (SELECT school_id,COUNT(*) users FROM users GROUP BY school_id) u ON u.school_id=s.id LEFT JOIN (SELECT school_id,COUNT(*) students FROM students WHERE deleted_at IS NULL GROUP BY school_id) st ON st.school_id=s.id LEFT JOIN subscriptions sub ON sub.school_id=s.id AND sub.status IN ('trial','active') LEFT JOIN subscription_plans sp ON sp.id=sub.plan_id ORDER BY s.id DESC");$schools=$stmt->fetchAll();admin_header('Super Admin');?><div class="content"><div class="cards"><div class="card"><div class="label">Schools</div><div class="metric"><?=count($schools)?></div></div><div class="card"><div class="label">Active schools</div><div class="metric"><?=count(array_filter($schools,fn($s)=>in_array($s['status'],['trial','active'],true)))?></div></div></div><div class="panel"><div class="panel-head"><h2>School tenants</h2></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Code</th><th>Status</th><th>Plan</th><th>Users</th><th>Students</th></tr></thead><tbody><?php foreach($schools as $s):?><tr><td><?=e($s['name'])?></td><td><?=e($s['code'])?></td><td><?=e($s['status'])?></td><td><?=e($s['plan']??'Unassigned')?></td><td><?=e($s['users'])?></td><td><?=e($s['students'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php admin_footer();
